/* ============ 共享原语：字节 / 编码 / 摘要 / ASN.1 / SSH wire ============
   这一段在四款工具里是同一份代码。之所以每个单文件都内联一遍而不抽包，
   是因为 nano-tools 的硬约束是「一个 HTML 双击即用、零依赖、可离线」。
   全部同步纯函数，不碰 WebCrypto，Node 里能直接跑已知答案向量。 */

function utf8Bytes(str){
