  s=String(s).replace(/[\s\r\n]/g,'').replace(/-/g,'+').replace(/_/g,'/').replace(/=+$/,'');
  var b=[],buf=0,bits=0;
  for(var i=0;i<s.length;i++){
    var v=B64A.indexOf(s[i]);
    if(v<0) throw new Error('base64 含非法字符 "'+s[i]+'"（第 '+(i+1)+' 位）');
    buf=(buf<<6)|v; bits+=6;
    if(bits>=8){ bits-=8; b.push((buf>>bits)&0xff); }
