function suggestAlg(jwk){
  if(!jwk||!jwk.kty) return null;
  if(jwk.kty==='RSA') return 'RS256';
  if(jwk.kty==='EC') return (EC_CURVES[jwk.crv]||{}).alg||null;
  if(jwk.kty==='OKP') return (OKP_CURVES[jwk.crv]||{}).alg||null;
  if(jwk.kty==='oct') return 'HS256';
