function keyBits(jwk){
  if(!jwk) return 0;
  if(jwk.kty==='RSA' && jwk.n) { try { return bitLen(b64uBytes(jwk.n)); } catch(e){ return 0; } }
  if(jwk.kty==='EC') return (EC_CURVES[jwk.crv]||{}).coord*8||0;
  if(jwk.kty==='OKP') return (OKP_CURVES[jwk.crv]||{}).len*8||0;
  if(jwk.kty==='oct' && jwk.k){ try { return b64uBytes(jwk.k).length*8; } catch(e){ return 0; } }
