function jwkToSpki(jwk){
  if(!jwk||!jwk.kty) return {error:'缺少 kty'};
  try {
    if(jwk.kty==='RSA'){
      if(!jwk.n||!jwk.e) return {error:'RSA 公钥需要 n 与 e'};
      var rsaPub=tlv(0x30, derUInt(b64uBytes(jwk.n)).concat(derUInt(b64uBytes(jwk.e))));
      return {value:tlv(0x30, algId(OID.rsa, derNull()).concat(derBitString(rsaPub)))};
    }
    if(jwk.kty==='EC'){
      var ci=EC_CURVES[jwk.crv];
      if(!ci) return {error:'不认识的 EC 曲线 "'+jwk.crv+'"'};
      if(!jwk.x||!jwk.y) return {error:'EC 公钥需要 x 与 y'};
      var X=pad(b64uBytes(jwk.x),ci.coord), Y=pad(b64uBytes(jwk.y),ci.coord);
      var point=[0x04].concat(X,Y);
      return {value:tlv(0x30, algId(OID.ecPublicKey, tlv(0x06, encodeOid(OID[jwk.crv]))).concat(derBitString(point)))};
    }
    if(jwk.kty==='OKP'){
      if(!OKP_CURVES[jwk.crv]) return {error:'不认识的 OKP 曲线 "'+jwk.crv+'"'};
      if(!jwk.x) return {error:'OKP 公钥需要 x'};
      return {value:tlv(0x30, algId(OID[jwk.crv], null).concat(derBitString(b64uBytes(jwk.x))))};
    }
    if(jwk.kty==='oct') return {error:'oct 是对称密钥，没有 SPKI 公钥表示'};
    return {error:'不支持的 kty "'+jwk.kty+'"'};
