        derUInt([0]), derUInt(b64uBytes(jwk.n)), derUInt(b64uBytes(jwk.e)), derUInt(b64uBytes(jwk.d)),
        derUInt(b64uBytes(jwk.p)), derUInt(b64uBytes(jwk.q)), derUInt(b64uBytes(jwk.dp)),
        derUInt(b64uBytes(jwk.dq)), derUInt(b64uBytes(jwk.qi))));
      return {value:tlv(0x30, [].concat(derUInt([0]), algId(OID.rsa, derNull()), tlv(0x04, inner)))};
    }
    if(jwk.kty==='EC'){
      var ci=EC_CURVES[jwk.crv];
