/* ---- DER → JWK ---- */
function readAlgId(node){
  var kids=derChildren(node.content);
  if(!kids.length || kids[0].tag!==0x06) return {error:'算法标识里没有 OID'};
  return {oid:decodeOid(kids[0].content), param:kids[1]||null};
}
function spkiToJwk(der){
  var top=derRead(der,0);
  if(!top||top.tag!==0x30) return {error:'最外层不是 SEQUENCE，这不像 SPKI'};
  var kids=derChildren(top.content);
  if(kids.length<2 || kids[0].tag!==0x30 || kids[1].tag!==0x03)
    return {error:'SPKI 应为 SEQUENCE{ AlgorithmIdentifier, BIT STRING }'};
  var ai=readAlgId(kids[0]);
  if(ai.error) return ai;
  var bits=kids[1].content;
  if(!bits.length) return {error:'BIT STRING 是空的'};
  if(bits[0]!==0) return {error:'BIT STRING 有 '+bits[0]+' 个未用位，公钥不该出现这种情况'};
  var key=bits.slice(1);
  var name=OID_REV[ai.oid];
  if(ai.oid===OID.rsa){
    var seq=derRead(key,0);
    if(!seq||seq.tag!==0x30) return {error:'RSA 公钥内层不是 SEQUENCE'};
    var nk=derChildren(seq.content);
    if(nk.length<2) return {error:'RSA 公钥应含 n 与 e 两个 INTEGER'};
    return {value:{kty:'RSA', n:bytesB64u(strip(nk[0].content)), e:bytesB64u(strip(nk[1].content))}};
  }
  if(ai.oid===OID.ecPublicKey){
    if(!ai.param || ai.param.tag!==0x06) return {error:'EC 公钥缺少曲线 OID 参数'};
    var crv=OID_REV[decodeOid(ai.param.content)];
    var ci=EC_CURVES[crv];
    if(!ci) return {error:'不支持的曲线 OID '+decodeOid(ai.param.content)};
    if(key[0]!==0x04) return {error:'EC 公钥点不是未压缩格式（首字节应为 0x04）'};
    if(key.length!==1+2*ci.coord) return {error:'曲线 '+crv+' 的点应为 '+(1+2*ci.coord)+' 字节，实际 '+key.length+' 字节'};
    return {value:{kty:'EC', crv:crv, x:bytesB64u(key.slice(1,1+ci.coord)), y:bytesB64u(key.slice(1+ci.coord))}};
  }
  if(OKP_CURVES[name]){
    if(key.length!==OKP_CURVES[name].len)
      return {error:name+' 公钥应为 '+OKP_CURVES[name].len+' 字节，实际 '+key.length+' 字节'};
    return {value:{kty:'OKP', crv:name, x:bytesB64u(key)}};
  }
