  var kids=derChildren(top.content);
  if(kids.length<3 || kids[0].tag!==0x02 || kids[1].tag!==0x30 || kids[2].tag!==0x04)
    return {error:'PKCS#8 应为 SEQUENCE{ INTEGER version, AlgorithmIdentifier, OCTET STRING }'};
  var ai=readAlgId(kids[1]);
  if(ai.error) return ai;
