    var seq=derRead(inner,0);
    if(!seq||seq.tag!==0x30) return {error:'RSAPrivateKey 内层不是 SEQUENCE'};
    var p=derChildren(seq.content);
    if(p.length<9) return {error:'RSAPrivateKey 需要 9 个 INTEGER（含 CRT 参数），实际 '+p.length+' 个'};
    return {value:{kty:'RSA', n:bytesB64u(strip(p[1].content)), e:bytesB64u(strip(p[2].content)),
      d:bytesB64u(strip(p[3].content)), p:bytesB64u(strip(p[4].content)), q:bytesB64u(strip(p[5].content)),
      dp:bytesB64u(strip(p[6].content)), dq:bytesB64u(strip(p[7].content)), qi:bytesB64u(strip(p[8].content))}};
  }
  if(ai.oid===OID.ecPublicKey){
    if(!ai.param||ai.param.tag!==0x06) return {error:'EC 私钥缺少曲线 OID'};
    var crv=OID_REV[decodeOid(ai.param.content)], ci=EC_CURVES[crv];
    if(!ci) return {error:'不支持的曲线 OID '+decodeOid(ai.param.content)};
    var es=derRead(inner,0);
    if(!es||es.tag!==0x30) return {error:'ECPrivateKey 内层不是 SEQUENCE'};
