    var oc=derRead(inner,0);
    if(!oc||oc.tag!==0x04) return {error:name+' 私钥内层应再套一层 OCTET STRING'};
    return {value:{kty:'OKP', crv:name, d:bytesB64u(oc.content)}};
  }
  return {error:'不支持的私钥算法 OID '+ai.oid};
}
function pemToJwk(text){
  var u=pemUnwrap(text);
