    if(/ENCRYPTED/.test(u.label)) return {error:'这是加密的 PKCS#8，需要先用口令解密（本工具不做口令解密）'};
    if(u.label==='RSA PRIVATE KEY') return {error:'这是 PKCS#1 格式，请先用 openssl pkcs8 -topk8 转成 PKCS#8'};
    if(u.label==='EC PRIVATE KEY') return {error:'这是 SEC1 格式，请先用 openssl pkcs8 -topk8 转成 PKCS#8'};
    var r=pkcs8ToJwk(u.der);
