  }
  if(u.label==='RSA PUBLIC KEY') return {error:'这是 PKCS#1 公钥，请先转成 SPKI（-----BEGIN PUBLIC KEY-----）'};
  if(u.label==='CERTIFICATE') return {error:'这是证书不是裸公钥，先用 openssl x509 -pubkey -noout 取出公钥'};
