function jwkToPem(jwk, wantPrivate){
  var r = wantPrivate ? jwkToPkcs8(jwk) : jwkToSpki(jwk);
  if(r.error) return r;
  return {value:pemWrap(wantPrivate?'PRIVATE KEY':'PUBLIC KEY', r.value), der:r.value};
}

