  'ssh-ed25519':'ed25519',
  'ecdsa-sha2-nistp256':'p256',
  'ecdsa-sha2-nistp384':'p384',
  'ecdsa-sha2-nistp521':'p521',
  'ssh-rsa':'rsa2048'
};
var SSH_CURVE_NAME = {'p256':'nistp256','p384':'nistp384','p521':'nistp521'};

function algOf(jwk){
  if(!jwk || !jwk.kty) return null;
  if(jwk.kty==='OKP'){
    if(jwk.crv==='Ed25519') return 'ed25519';
    if(jwk.crv==='X25519') return 'x25519';
    return null;
  }
  if(jwk.kty==='EC'){
    if(jwk.crv==='P-256') return 'p256';
    if(jwk.crv==='P-384') return 'p384';
    if(jwk.crv==='P-521') return 'p521';
    return null;
  }
  if(jwk.kty==='RSA'){
    var n=b64decode(jwk.n||''), bits=bitLen(n);
    if(bits<=2048) return 'rsa2048';
    if(bits<=3072) return 'rsa3072';
    return 'rsa4096';
  }
  return null;
}

/* ---- SSH wire ---- */
function mpint(mag){
  var i=0;
  while(i<mag.length-1 && mag[i]===0) i++;
  var m=mag.slice(i);
  if(m.length && (m[0]&0x80)) m=[0].concat(m);
  return sshStr(m);
}
function sshTypeOf(jwk){
  var a=algOf(jwk);
  if(!a) return null;
  return KP_ALGS[a].ssh;
}
function jwkToSshBlob(jwk){
  var a=algOf(jwk);
  if(!a) return {error:'认不出这是什么密钥，无法转成 OpenSSH 格式'};
  var spec=KP_ALGS[a];
  if(!spec.ssh) return {error:spec.label+' 不能做 SSH 认证密钥（它只用于密钥协商）'};
  if(jwk.kty==='OKP'){
    var A=b64decode(jwk.x||'');
    if(A.length!==32) return {error:'Ed25519 公钥应为 32 字节，实际 '+A.length+' 字节'};
    return {value: sshStr(utf8Bytes('ssh-ed25519')).concat(sshStr(A)), type:'ssh-ed25519'};
  }
  if(jwk.kty==='EC'){
    var L=spec.coordLen, x=b64decode(jwk.x||''), y=b64decode(jwk.y||'');
    if(x.length!==L || y.length!==L)
      return {error:spec.label+' 坐标应各为 '+L+' 字节，实际 x='+x.length+' y='+y.length};
    var pt=[4].concat(x, y);
    return {value: sshStr(utf8Bytes(spec.ssh)).concat(sshStr(utf8Bytes(SSH_CURVE_NAME[a])), sshStr(pt)),
            type: spec.ssh};
  }
  if(jwk.kty==='RSA'){
    var e=b64decode(jwk.e||''), n=b64decode(jwk.n||'');
    if(!e.length || !n.length) return {error:'RSA 公钥缺少 n 或 e'};
    return {value: sshStr(utf8Bytes('ssh-rsa')).concat(mpint(e), mpint(n)), type:'ssh-rsa'};
  }
  return {error:'kty '+jwk.kty+' 没有对应的 OpenSSH 表示'};
}
function stripLeadZero(b){
  var i=0;
  while(i<b.length-1 && b[i]===0) i++;
  return b.slice(i);
}
function padLeft(b, n){
  var out=stripLeadZero(b);
  if(out.length>n) return null;
  while(out.length<n) out=[0].concat(out);
  return out;
}
function sshBlobToJwk(blob){
  var r=sshRead(blob);
  if(r.trunc) return {error:'OpenSSH 数据在第 '+r.trunc.at+' 字节被截断（'+r.trunc.reason+'）'};
  if(!r.fields.length) return {error:'OpenSSH 数据是空的'};
  var type=bytesToUtf8(r.fields[0]);
  if(type==='ssh-ed25519'){
    if(r.fields.length<2) return {error:'ssh-ed25519 缺少公钥字段'};
    if(r.fields[1].length!==32) return {error:'ssh-ed25519 公钥应为 32 字节，实际 '+r.fields[1].length};
    return {value:{kty:'OKP', crv:'Ed25519', x:b64url(r.fields[1])}, type:type};
  }
  if(type.indexOf('ecdsa-sha2-')===0){
    if(r.fields.length<3) return {error:type+' 需要曲线名与坐标两个字段'};
    var cname=bytesToUtf8(r.fields[1]), pt=r.fields[2];
    var map={nistp256:['P-256',32], nistp384:['P-384',48], nistp521:['P-521',66]};
    var m=map[cname];
    if(!m) return {error:'不认识的曲线 "'+cname+'"'};
    if(pt[0]!==4) return {error:'这是压缩点（首字节 0x0'+pt[0]+'），JWK 只接受未压缩点，需要先解压'};
    if(pt.length!==1+m[1]*2) return {error:'坐标长度不对：'+cname+' 应为 '+(1+m[1]*2)+' 字节，实际 '+pt.length};
    return {value:{kty:'EC', crv:m[0],
                   x:b64url(pt.slice(1,1+m[1])), y:b64url(pt.slice(1+m[1]))}, type:type};
  }
  if(type==='ssh-rsa'){
    if(r.fields.length<3) return {error:'ssh-rsa 需要 e 与 n 两个字段'};
    return {value:{kty:'RSA', e:b64url(stripLeadZero(r.fields[1])), n:b64url(stripLeadZero(r.fields[2]))}, type:type};
  }
  if(type==='ssh-dss') return {error:'ssh-dss（DSA）已在 OpenSSH 7.0 默认禁用、9.8 起编译期移除，JWK 里也没有对应 kty。请直接换成 Ed25519。'};
  if(type.indexOf('sk-')===0) return {error:'这是 FIDO/U2F 硬件密钥（'+type+'），公钥后面还跟着 application 字段，不能直接当普通 JWK 用'};
  if(type.indexOf('-cert-v01@openssh.com')>0) return {error:'这是 SSH 证书而不是裸公钥，请先用 ssh-keygen -L 查看，或取出其中的 CA 公钥'};
  return {error:'不认识的 OpenSSH 密钥类型 "'+type+'"'};
}
function opensshToJwk(line){
  var t=String(line||'').trim();
  if(!t) return {error:'输入是空的'};
  var parts=t.split(/\s+/);
  var i=0;
  while(i<parts.length && !/^(ssh-|ecdsa-sha2-|sk-)/.test(parts[i])) i++;
  if(i>=parts.length) return {error:'这一行里找不到 ssh-* / ecdsa-sha2-* 开头的密钥类型'};
  if(i+1>=parts.length) return {error:'密钥类型 "'+parts[i]+'" 后面没有 base64 数据'};
  var b64=parts[i+1], blob;
  try { blob=b64decode(b64); }
  catch(e){ return {error:'base64 解不开：'+e.message}; }
  var r=sshBlobToJwk(blob);
  if(r.error) return r;
  var declared=parts[i], comment=parts.slice(i+2).join(' ');
  if(declared!==r.type)
    return {error:'行首写的是 "'+declared+'"，但 base64 里实际是 "'+r.type+'"。多半是复制时把两把密钥的片段拼在了一起。'};
  return {value:r.value, type:r.type, comment:comment, blob:blob};
}
function jwkToOpenssh(jwk, comment){
  var b=jwkToSshBlob(jwk);
  if(b.error) return b;
  var line=b.type+' '+b64encode(b.value);
  if(comment) line+=' '+String(comment).replace(/\s+/g,' ').trim();
  return {value:line, type:b.type, blob:b.value};
}

/* ---- 指纹 ---- */
function sshFingerprints(blob){
  return {
    sha256:'SHA256:'+b64encode(sha256Bytes(blob)).replace(/=+$/,''),
    md5:'MD5:'+colonHex(md5Bytes(blob))
  };
}
function spkiBitString(der){
  var seq=derRead(der,0);
  if(seq.error || seq.tag!==0x30) return null;
  var kids=derChildren(seq.content);
  if(!kids || kids.length<2) return null;
  var bs=kids[1];
  if(bs.tag!==0x03 || !bs.content.length) return null;
  return bs.content.slice(1);
}
function fingerprints(jwk){
  var out={}, pub=publicPart(jwk);
  var tp=thumbprint(pub);
  out.jwkThumb = tp.value || null;
  out.jwkThumbErr = tp.error || null;
  var spki=jwkToSpki(pub);
  if(spki.value){
    out.spkiPin='sha256/'+b64encode(sha256Bytes(spki.value));
    out.spkiSha256=colonHex(sha256Bytes(spki.value)).toUpperCase();
    var raw=spkiBitString(spki.value);
    out.x509Ski = raw ? toHex(sha1Bytes(raw)).toUpperCase() : null;
    out.spkiLen = spki.value.length;
  } else {
    out.spkiErr=spki.error;
  }
  var blob=jwkToSshBlob(pub);
  if(blob.value){
    var f=sshFingerprints(blob.value);
    out.sshSha256=f.sha256; out.sshMd5=f.md5; out.sshType=blob.type;
  } else {
    out.sshErr=blob.error;
  }
  return out;
}

/* ---- 配对校验 ---- */
function samePublic(a, b){
  var pa=publicPart(a), pb=publicPart(b);
  var ta=thumbprint(pa), tb=thumbprint(pb);
  if(ta.error) return {match:false, reason:'左边这把算不出指纹：'+ta.error};
  if(tb.error) return {match:false, reason:'右边这把算不出指纹：'+tb.error};
  if(ta.value===tb.value) return {match:true, thumbprint:ta.value, reason:'两边的 RFC 7638 指纹一致，是同一把密钥的公私两面。'};
  var why='指纹不同：'+ta.value+' ≠ '+tb.value;
  if(pa.kty!==pb.kty) why+='。kty 就已经不一样了（'+pa.kty+' vs '+pb.kty+'）';
  else if(pa.crv!==pb.crv) why+='。曲线不一样（'+pa.crv+' vs '+pb.crv+'）';
  return {match:false, reason:why};
}

/* ---- 全格式导出 ---- */
function allFormats(jwk, comment){
  var out={}, pub=publicPart(jwk), priv=hasPrivate(jwk);
  out.hasPrivate=!!priv;
  out.alg=algOf(pub);
  out.spec=out.alg?KP_ALGS[out.alg]:null;
  out.jwkPublic=JSON.stringify(pub,null,2);
  if(priv) out.jwkPrivate=JSON.stringify(jwk,null,2);
  var spki=jwkToSpki(pub);
  if(spki.value){ out.derPublic=spki.value; out.pemPublic=pemWrap('PUBLIC KEY',spki.value); }
  else out.pemPublicErr=spki.error;
  if(priv){
    var p8=jwkToPkcs8(jwk);
    if(p8.value){ out.derPrivate=p8.value; out.pemPrivate=pemWrap('PRIVATE KEY',p8.value); }
    else out.pemPrivateErr=p8.error;
  }
  var ssh=jwkToOpenssh(pub, comment);
  if(ssh.value){ out.openssh=ssh.value; out.sshType=ssh.type; }
  else out.opensshErr=ssh.error;
  out.fingerprints=fingerprints(pub);
  return out;
}

/* ---- 生成命令 ---- */
function genCommands(algKey, opts){
  opts=opts||{};
  var spec=KP_ALGS[algKey];
  if(!spec) return [];
  var comment=opts.comment||'you@example.com';
  var f=opts.file||'key';
  var cmds=[];
  function add(tool, cmd, note){ cmds.push({tool:tool, cmd:cmd, note:note}); }
  if(algKey==='ed25519'){
    add('ssh-keygen','ssh-keygen -t ed25519 -a 100 -C "'+comment+'" -f '+f,
        '-a 100 是 KDF 轮数，只影响私钥文件的口令保护强度，不影响密钥本身。');
    add('openssl','openssl genpkey -algorithm ed25519 -out '+f+'.pem',
        'OpenSSL 3.x 直出 PKCS#8，不需要再 -topk8。');
  } else if(algKey==='x25519'){
    add('openssl','openssl genpkey -algorithm x25519 -out '+f+'.pem',
        'X25519 只能做 ECDH，ssh-keygen 不会生成它。');
  } else if(algKey.indexOf('p')===0){
    var oname={p256:'prime256v1', p384:'secp384r1', p521:'secp521r1'}[algKey];
    var sshb={p256:256, p384:384, p521:521}[algKey];
    add('openssl','openssl genpkey -algorithm EC -pkeyopt ec_paramgen_curve:'+oname+' -out '+f+'.pem',
        'OpenSSL 里 P-256 叫 prime256v1，这个别名坑过很多人。');
    add('ssh-keygen','ssh-keygen -t ecdsa -b '+sshb+' -C "'+comment+'" -f '+f, null);
  } else {
    var bits={rsa2048:2048, rsa3072:3072, rsa4096:4096}[algKey];
    add('openssl','openssl genpkey -algorithm RSA -pkeyopt rsa_keygen_bits:'+bits+' -out '+f+'.pem',
        '别再用 openssl genrsa，它默认吐 PKCS#1，很多语言的库读不了。');
    add('ssh-keygen','ssh-keygen -t rsa -b '+bits+' -C "'+comment+'" -f '+f, null);
  }
  add('导出公钥','openssl pkey -in '+f+'.pem -pubout -out '+f+'.pub.pem', null);
  if(spec.ssh)
    add('PEM → OpenSSH','ssh-keygen -y -f '+f+'.pem > '+f+'.pub',
        'ssh-keygen -y 要求私钥文件权限是 600，否则直接拒绝读。');
  add('转 PKCS#8','openssl pkcs8 -topk8 -nocrypt -in '+f+'.pem -out '+f+'.p8.pem',
      '已经是 PKCS#8 时这条是幂等的，Java / Go 只认这个格式。');
  if(spec.ssh)
    add('SSH 指纹','ssh-keygen -lf '+f+'.pub', '输出的 SHA256: 值应与本页算出的一致。');
  add('证书固定指纹',
      'openssl pkey -pubin -in '+f+'.pub.pem -outform der | openssl dgst -sha256 -binary | openssl base64',
      '这就是 HPKP / 移动端证书固定用的那个 sha256/ 值。');
  return cmds;
}

/* ---- 选型建议 ---- */
var KP_SCENES = {
  ssh:      {label:'SSH 登录与部署', pick:'ed25519', also:['p256'], avoid:['rsa2048','x25519'],
             why:'OpenSSH 8.2 起 ed25519 是默认推荐；密钥短到能直接贴进配置文件，且没有曲线参数可以选错。'},
  jwt:      {label:'JWT / OIDC 签名', pick:'ed25519', also:['p256','rsa2048'],
             avoid:[],
             why:'新系统首选 EdDSA；若验证方是老 Java 或第三方 IdP，退回 ES256，再不行才用 RS256。'},
  tls:      {label:'TLS 服务器证书', pick:'p256', also:['rsa2048','p384'], avoid:['ed25519','x25519'],
             why:'截至 2026 年主流公共 CA 仍不签发 Ed25519 证书，P-256 是握手最快又全兼容的选择。'},
  device:   {label:'嵌入式 / IoT 设备', pick:'ed25519', also:['p256'], avoid:['rsa3072','rsa4096'],
             why:'RSA 在 MCU 上生成一次密钥可能要几十秒，Ed25519 是毫秒级，栈占用也小一个量级。'},
  longterm: {label:'离线根密钥 / CA', pick:'p384', also:['rsa4096','ed25519'], avoid:[],
             why:'根密钥要活十几年，选强度冗余大的；同时确认你的 HSM 支持——很多 HSM 至今不支持 Ed25519。'},
  exchange: {label:'密钥协商 / 加密信封', pick:'x25519', also:['p256'], avoid:['ed25519','rsa2048'],
             why:'签名密钥和协商密钥必须分开。Ed25519 与 X25519 数学上相关但用途不可互换。'}
};
function advise(scene){
  var s=KP_SCENES[scene];
  if(!s) return {error:'没有这个场景'};
  function line(k, tone){
    var a=KP_ALGS[k];
    return {alg:k, label:a.label, tone:tone, bits:a.sec+' 位安全强度', good:a.good, bad:a.bad};
  }
  var rows=[line(s.pick,'ok')];
  for(var i=0;i<s.also.length;i++) rows.push(line(s.also[i],'info'));
  for(var j=0;j<s.avoid.length;j++) rows.push(line(s.avoid[j],'warn'));
  return {label:s.label, why:s.why, rows:rows};
}

/* ---- 输入识别 ---- */
function detectKey(text){
  var t=String(text||'').replace(/^\uFEFF/,'').trim();
  if(!t) return {error:'输入是空的'};
  if(/-----BEGIN [A-Z0-9 ]+-----/.test(t)){
    var r=pemToJwk(t);
    if(r.error) return {error:r.error};
    return {value:r.value, from:'PEM'};
  }
  if(/^(ssh-|ecdsa-sha2-|sk-)/.test(t) || /\s(ssh-ed25519|ssh-rsa|ecdsa-sha2-nistp\d+)\s/.test(t)){
    var s=opensshToJwk(t.split(/\r?\n/)[0]);
    if(s.error) return {error:s.error};
    return {value:s.value, from:'OpenSSH', comment:s.comment};
  }
  if(t.charAt(0)==='{'){
    var j=jsonParse(t);
    if(j.error) return {error:j.error};
    var o=j.value;
    if(o && o.keys && o.keys.length) return {value:o.keys[0], from:'JWKS 的第一把'};
    return {value:o, from:'JWK'};
  }
  if(/^[0-9a-fA-F\s]+$/.test(t) && t.replace(/\s/g,'').length>=40){
    try {
      var der=fromHex(t.replace(/\s/g,''));
      var k=spkiToJwk(der);
      if(k.value) return {value:k.value, from:'DER（hex）'};
      var k2=pkcs8ToJwk(der);
      if(k2.value) return {value:k2.value, from:'DER（hex，PKCS#8）'};
      return {error:k.error};
    } catch(e){ return {error:'hex 解不开：'+e.message}; }
  }
  return {error:'认不出输入格式。支持 PEM、JWK/JWKS、OpenSSH 单行公钥，以及 DER 的十六进制。'};
}

